void print_request_tokens(char *user_id, char *auth_token, bool exist_access, char *access_token,
						  bool exist_refresh, char *refresh_token)
{
	printf("BEGIN %s AUTHZ\n  RequestToken = %s\n", user_id, auth_token);
	if (exist_access) {
		printf("  AccessToken = %s\n", access_token);
		if (exist_refresh)
			printf("  RefreshToken = %s\n", refresh_token);
	}
}

response_get_auth_token *
request_auth_token_1_svc(request_start_auth arg1,  struct svc_req *rqstp)
{
	static response_get_auth_token result;

	std::string user_id_string = std::string(arg1.user_id);

	bool found_user = false;
	for (auto &user : users_database)
		if (user.user_id == user_id_string)
			found_user = true;

	// user was not found in the database
	if (!found_user) {
		const char *user_not_found = USER_NOT_FOUND;
		result.auth_token = new char[TOKEN_LEN + 1];
		result.is_error = true;
		result.message = new char[strlen(user_not_found) + 1];
		strcpy(result.message, user_not_found);
		printf("BEGIN %s AUTHZ\n", arg1.user_id);
		return &result;
	}

	const char *succes = "SUCCES";
	result.auth_token = generate_access_token(arg1.user_id);
	result.is_error = false;
	result.message = new char[strlen(succes) + 1];
	strcpy(result.message, succes);

	for (auto &user : users_database)
		if (user.user_id == user_id_string)
			user.auth_token = std::string(result.auth_token);

	return &result;
}

std::vector<std::pair<std::string, std::string>> extract_string_pairs(const std::string& inputString) {
    std::stringstream ss(inputString);
    std::string token;
    std::vector<std::pair<std::string, std::string>> stringPairs;

    while (std::getline(ss, token, ',')) {
        std::pair<std::string, std::string> stringPair;
        stringPair.first = token;

        if (std::getline(ss, token, ',')) {
            stringPair.second = token;
            stringPairs.push_back(stringPair);
        }
    }

    return stringPairs;
}

response_approve_auth *
approve_auth_token_1_svc(start_approve_auth arg1,  struct svc_req *rqstp)
{
	static response_approve_auth result;

	result.auth_token = new char[TOKEN_LEN + 1];
	strcpy(result.auth_token, arg1.auth_token);

	if (!approvals.empty()) {
		std::string permissions = approvals.front();

		approvals.erase(approvals.begin());

		if (permissions == "*,-") {
			result.is_signed = false;
		} else {
			result.is_signed = true;

			std::vector<std::pair<std::string, std::string>> pairs = extract_string_pairs(permissions);

			std::unordered_map<std::string, std::vector<std::string>> user_perms;
			for (auto &pair : pairs) {
				for (int i = 0; i < pair.second.length(); i++) {
					std::string resource = std::string(pair.first);
					switch (pair.second[i]) {
						case 'R':
							user_perms[resource].push_back(READ);
							break;
						case 'I':
							user_perms[resource].push_back(INSERT);
							break;
						case 'M':
							user_perms[resource].push_back(MODIFY);
							break;
						case 'D':
							user_perms[resource].push_back(DELETE);						
							break;
						case 'X':
							user_perms[resource].push_back(EXECUTE);						
							break;
						default:
							break;
					}
				}
			}

			// create new permissions map
			for (auto &user : users_database) {
				if (user.auth_token == std::string(result.auth_token))
					user.permissions = user_perms;
			}
		}
	}

	return &result;
}

response_start_auth *
request_bearer_token_1_svc(request_bearer_token_args arg1,  struct svc_req *rqstp)
{
	static response_start_auth result;

	if (!arg1.is_signed) {
		result.token_lifetime = -1;
		const char *request_denied = REQUEST_DENIED;
		result.is_error = true;
		result.message = new char[strlen(request_denied) + 1];
		strcpy(result.message, request_denied);

		// print only the request token for this request
		print_request_tokens(arg1.user_id, arg1.auth_token,
							 false, NULL, false, NULL);
		return &result;
	}

	result.access_token = generate_access_token(arg1.auth_token);
	if (arg1.automatic_refresh) {
		result.refresh_token = generate_access_token(result.access_token);
		print_request_tokens(arg1.user_id, arg1.auth_token,
							true, result.access_token, true, result.refresh_token);
	} else {
		result.refresh_token = new char[TOKEN_LEN + 1];
		print_request_tokens(arg1.user_id, arg1.auth_token,
							true, result.access_token, false, NULL);
	}

	result.token_lifetime = token_lifetime;
	result.is_error = false;
	result.message = new char[TOKEN_LEN + 1];

	// update database
	for (auto &user : users_database) {
		std::string user_id_string = std::string(arg1.user_id);

		// find an user with that user_id and update acces_token, refresh_token
		// and token_lifetime
		if (user.user_id == user_id_string) {
			user.access_token = std::string(result.access_token);
			user.tokens_lifetime = token_lifetime;
			if (arg1.automatic_refresh)
				user.refresh_token = std::string(result.refresh_token);
			user.automatic_refresh = arg1.automatic_refresh;
			break;
		}
	}

	return &result;
}

