	bool found_user = false;
	char *new_access_token, *new_refresh_token;
	for (auto &user: users_database) {
		if (user.access_token == std::string(arg1.access_token)) {
			new_access_token = generate_access_token((char *) user.refresh_token.c_str());
			new_refresh_token = generate_access_token(new_access_token);
			user.access_token = std::string(new_access_token);
			user.refresh_token = std::string(new_refresh_token);
			user.tokens_lifetime = token_lifetime;

			printf("BEGIN %s AUTHZ REFRESH\n", user.user_id.c_str());
			printf("  AccessToken = %s\n", user.access_token.c_str());
			printf("  RefreshToken = %s\n", user.refresh_token.c_str());

			result.access_token = new_access_token;
			result.is_error = false;
			found_user = true;
			break;
		}
	}

	if (!found_user) {
		result.is_error = true;
		result.access_token = strdup(EMPTY_TOKEN);
		return &result;
	}

	return &result;
